public class SorterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<String> fruits = new java.util.ArrayList<>(java.util.List.of("banana", "fig", "apple"));
        Sorter.sortByLength(fruits);
        check("sortByLength basic", "[fig, apple, banana]", fruits.toString());
        java.util.List<String> stable = new java.util.ArrayList<>(java.util.List.of("bb", "aa", "cc", "d"));
        Sorter.sortByLength(stable);
        check("sortByLength is stable", "[d, bb, aa, cc]", stable.toString());
        java.util.List<String> single = new java.util.ArrayList<>(java.util.List.of("only"));
        Sorter.sortByLength(single);
        check("sortByLength single element", "[only]", single.toString());
        java.util.List<String> byLast = new java.util.ArrayList<>(java.util.List.of("cab", "tic", "area"));
        Sorter.sortByLastChar(byLast);
        check("sortByLastChar basic", "[area, cab, tic]", byLast.toString());
        java.util.List<String> reversed = new java.util.ArrayList<>(java.util.List.of("az", "by", "cx"));
        Sorter.sortByLastChar(reversed);
        check("sortByLastChar reverses", "[cx, by, az]", reversed.toString());
        java.util.List<String> empty = new java.util.ArrayList<>();
        Sorter.sortByLastChar(empty);
        check("sortByLastChar empty list", "[]", empty.toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

