public class Sorter {

    public static void sortByLength(java.util.List<String> words) {
        words.sort(java.util.Comparator.comparingInt(String::length));
    }

    public static void sortByLastChar(java.util.List<String> words) {
        words.sort(java.util.Comparator.comparingInt((String w) -> w.charAt(w.length() - 1)));
    }
}
